mapper.select:
select 
from platform_app_service
where app_id = #{appId,jdbcType=VARCHAR} and service_key = #{serviceKey,jdbcType=VARCHAR}

mapper.update:
update platform_app_service

  desired_json = #{desiredJson,jdbcType=LONGVARCHAR},
  pending_delete = #{pendingDelete,jdbcType=TINYINT},
  version = version + 1,
  updated_at = #{updatedAt,jdbcType=TIMESTAMP}

where id = #{id,jdbcType=BIGINT} and version = #{version,jdbcType=INTEGER}
